v = {'ans': 0.0, 'E': m.e, 'PI': m.pi}
assert statement(TokenizeWrapper('sqrt(9)'), v) == 3.0
assert statement(TokenizeWrapper('ans + sqrt(0)'), v) == 3.0
try:
    statement(TokenizeWrapper('sqrt(-5)*sqrt(-5)'), v)
    assert False, 'Expected EvaluationError'
except EvaluationError:
    pass

v = {'ans': 0.0, 'E': m.e, 'PI': m.pi}
assert abs(statement(TokenizeWrapper('log(E)'), v) - 1.0) < 1e-6
assert abs(statement(TokenizeWrapper('log(100, 10)'), v) - 2.0) < 1e-6
assert abs(statement(TokenizeWrapper('log(49, 7)'), v) - 2.0) < 1e-6
for bad in ['log(2, 3, 4)', 'log(0)', 'log(2, -3)']:
    try:
        statement(TokenizeWrapper(bad), v)
        assert False, f'Expected EvaluationError on {bad}'
    except EvaluationError:
        pass

v = {'ans': 0.0}
assert statement(TokenizeWrapper('divisible(4, 2)'), v) == 4.0
assert statement(TokenizeWrapper('divisible(60, 7)'), v) == 7.0
for bad in ['divisible(60, -3)', 'divisible(-2, 2)', 'divisible(0)', 'divisible(1, 2, 3)']:
    try:
        statement(TokenizeWrapper(bad), v)
        assert False, f'Expected EvaluationError on {bad}'
    except EvaluationError:
        pass
